#!/usr/bin/env bash

set -euo pipefail
upstream=redhat-openshift-ecosystem/community-operators-prod
branch="openstack-lightspeed-release-$NEW_VERSION"
title="operator openstack-lightspeed-operator ($NEW_VERSION)"
head="${FORK_REPOSITORY%%/*}:$branch"

gh auth setup-git --hostname github.com
git config user.name "$AUTHOR_NAME"
git config user.email "$AUTHOR_EMAIL"
git remote add fork "https://github.com/$FORK_REPOSITORY.git"
remote_head=$(git ls-remote fork "refs/heads/$branch" | cut -f1)
git switch -c "$branch"
git add -- "operators/openstack-lightspeed-operator/$NEW_VERSION"
git commit --signoff -m "$title"
# Only replace the branch if it has not changed since we read it.
git push --force-with-lease="refs/heads/$branch:$remote_head" \
  fork "HEAD:refs/heads/$branch"

body_file="$RUNNER_TEMP/community-release-pr.md"
cat > "$body_file" <<EOF
Release OpenStack Lightspeed community operator $NEW_VERSION.

- Image tag: $CONTAINER_IMAGE_TAG
- Bundle image: quay.io/openstack-lightspeed/operator-bundle@$BUNDLE_DIGEST
- Operator image: quay.io/openstack-lightspeed/operator@$OPERATOR_DIGEST

Generated by [this workflow run]($GITHUB_SERVER_URL/$GITHUB_REPOSITORY/actions/runs/$GITHUB_RUN_ID).
EOF

# REST calls through gh support both personal and organization forks.
pr_number=$(gh api --method GET "repos/$upstream/pulls" \
  -f state=open -f base=main -f "head=$head" --jq '.[0].number // empty')
if [[ -n "$pr_number" ]]; then
  pr_url=$(gh api --method PATCH "repos/$upstream/pulls/$pr_number" \
    -f "title=$title" -F "body=@$body_file" --jq .html_url)
else
  pr_url=$(gh api --method POST "repos/$upstream/pulls" \
    -f base=main -f "head=$head" -f "head_repo=${FORK_REPOSITORY#*/}" \
    -f "title=$title" -F "body=@$body_file" --jq .html_url)
fi
echo "pull-request-url=$pr_url" >> "$GITHUB_OUTPUT"
